/* === КАРТОЧКА ТОВАРА: универсальная зачистка === */
/* Скрываем по href и data-атрибутам */
a[href*="compare"],a[href*="wishlist"],
button[data-action="compare"],button[data-action="wishlist"],
.product__action a,.product__action button{display:none !important}

/* Скрываем по тексту (если есть label или span с текстом) */
.product__info span:has(+ .product__stock),
.product__info .product__stock,
.product__info .product__availability,
.product__info .product__status{display:none !important}

/* Код товара */
.product__info .product__model,
.product__info .product__sku,
.product__info .product__code,
.product__info dt:has(+ dd),
.product__info dd{display:none !important}

/* Кнопки: flex-ряд, одинаковая ширина */
.product__buy,.product__actions,.product__cart{display:flex !important;gap:12px;flex-wrap:wrap;align-items:stretch}
.product__buy .ui-btn,.product__buy button,.product__buy a,
.product__actions .ui-btn,.product__actions button,
.product__cart .ui-btn,.product__cart button{
flex:1 1 220px !important;min-height:56px;display:inline-flex !important;
align-items:center;justify-content:center;gap:10px;border-radius:12px !important;
border:0 !important;box-shadow:none !important;margin:0 !important;
font-family:var(--font-body) !important;font-weight:600 !important;font-size:16px !important}

/* === 26. СТРАНИЦА ТОВАРА (sku): зачистка и кнопки === */
/* 1) Убираем «В избранное» и «В сравнение» вместе с полосой-группой */
.sku__addto{display:none !important}
.sku__group:has(.sku__addto){display:none !important}
/* 2) Убираем состояние склада */
.sku__availability{display:none !important}
/* 3) Убираем код товара */
.sku__id{display:none !important}
/* 4) «Купить» + «Быстрый заказ»: ровный ряд одинаковых кнопок */
.sku__action .row{display:flex;flex-wrap:wrap;align-items:stretch;gap:12px;margin:0}
.sku__action .col-md-auto{flex:1 1 240px;width:auto;max-width:100%;padding:0}
.sku__action .ui-add-to-cart{display:flex;flex-wrap:wrap;gap:12px}
.sku__action .ui-btn{width:100%;min-height:56px;border-radius:12px;border:0;margin:0;box-shadow:none;outline:none;display:inline-flex;align-items:center;justify-content:center;gap:10px;font-family:var(--font-body);font-weight:600;font-size:16px;padding:0 28px}
.sku__action .ui-btn--primary{background:var(--cp-acc);color:#fff}
