<script>
(function () {
  function unlock(d) {
    var box = d.closest('.js-readmore') ||
              d.closest('.details__txt-readmore') ||
              d.closest('.details__txt');
    if (box) { box.style.maxHeight = 'none'; box.style.overflow = 'visible'; }
  }
  document.addEventListener('toggle', function (e) {
    if (e.target && e.target.tagName === 'DETAILS' && e.target.open) unlock(e.target);
  }, true);
  function init() {
    document.querySelectorAll('details[open]').forEach(unlock);
  }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init);
  else init();
})();
